package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen1Test {

    private TypeDeserializerBaseBase testInstance;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JavaType mockBaseType;

    // Concrete implementation to test the protected method
    private static class TypeDeserializerBaseBase extends TypeDeserializerBase {

        protected TypeDeserializerBaseBase(JavaType baseType, TypeIdResolver idRes, String typePropertyName, boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        // Overriding protected methods to control behavior for testing
        @Override
        protected JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return _findDeserializerSpy(ctxt, typeId);
        }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return _findDefaultImplDeserializerSpy(ctxt);
        }

        // Spy hooks
        protected JsonDeserializer<Object> _findDeserializerSpy(DeserializationContext ctxt, String typeId) throws IOException {
            return null;
        }

        protected JsonDeserializer<Object> _findDefaultImplDeserializerSpy(DeserializationContext ctxt) throws IOException {
            return null;
        }

        // Required abstract implementations
        @Override public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) { return null; }
        @Override public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override public String baseTypeName() { return "test"; }
        @Override public String getPropertyName() { return "prop"; }
        @Override public TypeIdResolver getTypeIdResolver() { return null; }
        @Override public Class<?> getDefaultImpl() { return null; }
        @Override public JavaType baseType() { return mockBaseType; }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockBaseType = mock(JavaType.class);
        testInstance = spy(new TypeDeserializerBaseBase(mockBaseType, null, "type", true, null));
    }

    @Test
    public void test_deserializeWithNativeTypeId_nullTypeId_foundDefaultDeserializer() throws IOException {
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        Object expectedResult = "success";

        doReturn(mockDeser).when(testInstance)._findDefaultImplDeserializerSpy(mockContext);
        when(mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object actualResult = testInstance._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertEquals(expectedResult, actualResult);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void test_deserializeWithNativeTypeId_nullTypeId_noDefaultDeserializer_reportsMismatch() throws IOException {
        doReturn(null).when(testInstance)._findDefaultImplDeserializerSpy(mockContext);
        String errorMessage = "No (native) type id found";
        when(mockContext.reportInputMismatch(eq(mockBaseType), any(String.class))).thenReturn(new RuntimeException(errorMessage));

        Object result = testInstance._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertTrue(result instanceof RuntimeException);
        assertEquals(errorMessage, ((RuntimeException) result).getMessage());
        verify(mockContext).reportInputMismatch(eq(mockBaseType), any(String.class));
    }

    @Test
    public void test_deserializeWithNativeTypeId_stringTypeId() throws IOException {
        String typeId = "StringId";
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        Object expectedResult = "success_string";

        doReturn(mockDeser).when(testInstance)._findDeserializerSpy(mockContext, typeId);
        when(mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object actualResult = testInstance._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, actualResult);
        verify(testInstance)._findDeserializerSpy(mockContext, typeId);
    }

    @Test
    public void test_deserializeWithNativeTypeId_nonStringTypeId_convertsToString() throws IOException {
        Integer typeId = 123;
        String typeIdStr = "123";
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        Object expectedResult = "success_int";

        doReturn(mockDeser).when(testInstance)._findDeserializerSpy(mockContext, typeIdStr);
        when(mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object actualResult = testInstance._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, actualResult);
        verify(testInstance)._findDeserializerSpy(mockContext, typeIdStr);
    }

    @Test
    public void test_deserializeWithNativeTypeId_complexObjectTypeId() throws IOException {
        Object complexId = new Object();
        String complexIdStr = complexId.toString();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        Object expectedResult = "success_complex";

        doReturn(mockDeser).when(testInstance)._findDeserializerSpy(mockContext, complexIdStr);
        when(mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object actualResult = testInstance._deserializeWithNativeTypeId(mockParser, mockContext, complexId);

        assertEquals(expectedResult, actualResult);
        verify(testInstance)._findDeserializerSpy(mockContext, complexIdStr);
    }
}
